/**
 * Small helpers for the files the browser hands to the user.
 */

/**
 * Offers a text as a download.
 *
 * The CloudFormation template is generated by the API, so the customer gets
 * it as a file they can upload to the CloudFormation console.
 */
export function downloadText(filename: string, content: string, mimeType = "text/plain") {
  const blob = new Blob([content], { type: `${mimeType};charset=utf-8` });
  const url = URL.createObjectURL(blob);

  const link = document.createElement("a");
  link.href = url;
  link.download = filename;

  document.body.appendChild(link);
  link.click();
  link.remove();

  URL.revokeObjectURL(url);
}

/**
 * Copies a text to the clipboard.
 *
 * The clipboard API is only available on a secure origin, so the fallback
 * keeps the button working when the app runs on a plain http host.
 */
export async function copyText(content: string): Promise<boolean> {
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(content);
      return true;
    }
  } catch {
    // The permission was refused or the origin is not secure, the fallback
    // below still works.
  }

  try {
    const area = document.createElement("textarea");
    area.value = content;
    area.setAttribute("readonly", "");
    area.style.position = "fixed";
    area.style.opacity = "0";

    document.body.appendChild(area);
    area.select();

    const copied = document.execCommand("copy");
    area.remove();

    return copied;
  } catch {
    return false;
  }
}
